export const samePosition=(a,b)=>Math.abs(a.x-b.x)<1e-7&&Math.abs(a.z-b.z)<1e-7;
const copy=p=>({x:p.x,z:p.z});
export function createDeliveryModel(){
 const route=[{id:'S1',name:'Market Street',start:{x:-12,z:8},end:{x:-2,z:8},clearWidth:1.6,blocked:false},{id:'S2',name:'Garden Passage',start:{x:-2,z:8},end:{x:-2,z:-4},clearWidth:1.2,blocked:false},{id:'S3',name:'Canal Walk',start:{x:-2,z:-4},end:{x:10,z:-4},clearWidth:1.4,blocked:false},{id:'S4',name:'Willow Lane',start:{x:10,z:-4},end:{x:10,z:-10},clearWidth:1.1,blocked:false}];
 const state={robot:{id:'R-01',position:copy(route[0].start),width:.7,payloadCapacity:5,motionState:'idle',carryingId:null,traversingId:null},package:{id:'PKG-001',weight:2.4,pickup:copy(route[0].start),destination:copy(route.at(-1).end),position:copy(route[0].start),deliveryStatus:'waiting',carriedBy:null},segments:route,nextIndex:0,movement:null,distance:0,history:[{message:'Robot is idle at pickup. Package is waiting.',kind:'info'}]};
 function log(message,kind='info'){state.history.push({message,kind});if(state.history.length>40)state.history.shift();return{ok:true,message};}
 function stationary(){if(state.robot.motionState==='moving'||state.movement)throw new Error('Finish the current movement before starting another action.');}
 function validate(){const r=state.robot,p=state.package;if(!Number.isFinite(r.width)||r.width<=0||!Number.isFinite(r.payloadCapacity)||r.payloadCapacity<=0||!Number.isFinite(p.weight)||p.weight<=0)throw new Error('Weight, robot width and payload capacity must be greater than zero.');state.segments.forEach(s=>{if(!Number.isFinite(s.clearWidth)||s.clearWidth<0)throw new Error('Path clear width cannot be negative.');for(const pos of[s.start,s.end])if(!Number.isFinite(pos.x)||!Number.isFinite(pos.z))throw new Error('Coordinates must be finite.');});const carried=r.carryingId===p.id&&p.carriedBy===r.id;if((p.deliveryStatus==='in transit')!==carried||(!carried&&(r.carryingId!==null||p.carriedBy!==null)))throw new Error('The carrying relationship must match package status.');if(carried&&!samePosition(r.position,p.position))throw new Error('The carried package must move with the robot.');if((r.motionState==='moving')!==!!state.movement||(!!state.movement)!==(r.traversingId!==null))throw new Error('Traversal must match motion state.');return true;}
 function pickup(){stationary();const r=state.robot,p=state.package;if(p.deliveryStatus!=='waiting')throw new Error(p.deliveryStatus==='delivered'?'This package has already been delivered.':'The package is already in transit.');if(r.carryingId!==null||p.carriedBy!==null)throw new Error('The robot can carry only one package.');if(!samePosition(r.position,p.pickup))throw new Error('The robot must be at the pickup position.');if(p.weight>r.payloadCapacity)throw new Error('The package exceeds the robot’s payload capacity.');r.carryingId=p.id;p.carriedBy=r.id;p.deliveryStatus='in transit';p.position=copy(r.position);r.motionState='idle';validate();return log('Package collected. Ready to move.','success');}
 function move(){stationary();const r=state.robot;if(r.carryingId!==state.package.id)throw new Error('Pick up the package before moving.');const segment=state.segments[state.nextIndex];if(!segment)throw new Error('The route is complete. Deliver the package.');if(!samePosition(r.position,segment.start))throw new Error('The next segment is disconnected from the robot’s position.');if(segment.blocked||segment.clearWidth<=r.width){r.motionState='waiting';validate();return{...log(segment.blocked?`${segment.id} is blocked. Robot is waiting.`:`${segment.id} is too narrow. Robot is waiting.`,'warning'),ok:false};}r.motionState='moving';r.traversingId=segment.id;state.movement={segmentId:segment.id,start:copy(segment.start),end:copy(segment.end),progress:0,length:Math.hypot(segment.end.x-segment.start.x,segment.end.z-segment.start.z),duration:Math.max(1800,Math.hypot(segment.end.x-segment.start.x,segment.end.z-segment.start.z)*250)};validate();return log(`Traversing ${segment.id} · ${segment.name}.`);}
 function advance(milliseconds){if(!state.movement)return;const m=state.movement;if(!Number.isFinite(milliseconds)||milliseconds<0)throw new Error('Elapsed time must be nonnegative.');m.progress=Math.min(1,m.progress+milliseconds/m.duration);state.robot.position={x:m.start.x+(m.end.x-m.start.x)*m.progress,z:m.start.z+(m.end.z-m.start.z)*m.progress};state.package.position=copy(state.robot.position);if(m.progress===1){state.robot.position=copy(m.end);state.package.position=copy(m.end);state.distance+=m.length;state.nextIndex++;state.robot.traversingId=null;state.robot.motionState='idle';state.movement=null;log(state.nextIndex===state.segments.length?'Destination reached. Press Deliver to complete the handoff.':`${m.segmentId} complete. Ready for the next segment.`,'success');}validate();}
 function wait(){stationary();state.robot.motionState='waiting';validate();return log(state.robot.carryingId?'Robot is waiting. Package stays on board.':'Robot is waiting at pickup. Package is not yet collected.');}
 function deliver(){stationary();const r=state.robot,p=state.package;if(r.carryingId!==p.id||p.carriedBy!==r.id)throw new Error('The robot must be carrying the package.');if(!samePosition(r.position,p.destination))throw new Error('Reach the destination before delivering.');r.carryingId=null;p.carriedBy=null;p.position=copy(p.destination);p.deliveryStatus='delivered';r.motionState='idle';validate();return log('Package delivered. Delivery complete.','success');}
 function updateSegment(id,changes){stationary();const s=state.segments.find(s=>s.id===id);if(!s)throw new Error('Choose an existing path segment.');if('clearWidth'in changes&&(!Number.isFinite(changes.clearWidth)||changes.clearWidth<0))throw new Error('Clear width must be zero or greater.');if('blocked'in changes&&typeof changes.blocked!=='boolean')throw new Error('Blocked must be true or false.');if('clearWidth'in changes)s.clearWidth=changes.clearWidth;if('blocked'in changes)s.blocked=changes.blocked;validate();return log(`${s.id} passage updated. ${s.blocked?'Blocked.':s.clearWidth<=state.robot.width?'Too narrow.':'Passable.'}`);}
 function updateSpecs(changes){stationary();if(state.package.deliveryStatus!=='waiting')throw new Error('Robot and package specifications can be edited before pickup.');for(const[k,value]of Object.entries(changes)){if(!['weight','width','payloadCapacity'].includes(k)||!Number.isFinite(value)||value<=0)throw new Error('Enter a number greater than zero.');}if('weight'in changes)state.package.weight=changes.weight;if('width'in changes)state.robot.width=changes.width;if('payloadCapacity'in changes)state.robot.payloadCapacity=changes.payloadCapacity;validate();return log('Delivery specifications updated.');}
 validate();return{state,pickup,move,wait,deliver,advance,updateSegment,updateSpecs,validate};
}
